# alarm: a Moore machine, generated by Silinx from the Petri net alarm.pn.json (edit the drawing, not this file).
# MicroPython for the ESP32 DevKit. One tick every TICK_MS milliseconds: the inputs read once at its start, the outputs
# written to their pins at its end (Silinx's synchronous reactive model: docs/SYSTEMS.md).
# Inputs: fail GPIO4, opened GPIO13.
# Outputs: fails GPIO14 GPIO16, alarm GPIO17.
# (a port of several bits: its pins bit 0 first)

from machine import Pin
import time

# ---- the pins
PIN_FAIL = Pin(4, Pin.IN)
PIN_OPENED = Pin(13, Pin.IN)
PIN_FAILS = (Pin(14, Pin.OUT), Pin(16, Pin.OUT))
PIN_ALARM = Pin(17, Pin.OUT)

TICK_MS = 10  # the tick's period

# ---- the states
S_none = 0  # none=1, one=0, two=0, alarmed=0
S_one = 1  # none=0, one=1, two=0, alarmed=0
S_two = 2  # none=0, one=0, two=1, alarmed=0
S_alarmed = 3  # none=0, one=0, two=0, alarmed=1

# ---- the inputs, read once per tick
fail = 0
opened = 0

# ---- the outputs
fails = 0  # 2 bits
alarm = 0

# ---- the memory
state = S_none


# a number to its pins, bit 0 first
def write_bits(pins, v):
    for i in range(len(pins)):
        pins[i].value((v >> i) & 1)


def read_inputs():
    global fail, opened
    fail = PIN_FAIL.value()
    opened = PIN_OPENED.value()


def write_outputs():
    write_bits(PIN_FAILS, fails)
    PIN_ALARM.value(alarm)


# the reset state
def reset_machine():
    global state
    state = S_none


# one tick: the outputs of the present state and of the inputs, then the next state
def step_machine():
    global state, fails, alarm
    read_inputs()
    # the outputs' defaults
    fails = 0
    alarm = 0
    if state == S_none:
        if fail:
            state = S_one
    elif state == S_one:
        fails = 1
        if not fail and opened:
            state = S_none
        elif fail:
            state = S_two
    elif state == S_two:
        fails = 2
        if not fail and opened:
            state = S_none
        elif fail:
            state = S_alarmed
    elif state == S_alarmed:
        fails = 3
        alarm = 1
    write_outputs()


# the reset state, then a tick every TICK_MS milliseconds
def main():
    reset_machine()
    last = time.ticks_ms()
    while True:
        if time.ticks_diff(time.ticks_ms(), last) >= TICK_MS:
            last = time.ticks_add(last, TICK_MS)
            step_machine()


main()
